export type KanaScript = 'hiragana' | 'katakana'

export interface KanaExample {
  word: string
  meaning: string
}

export interface Kana {
  id: string
  script: KanaScript
  character: string
  romaji: string
  // Traces SVG (même format que Kanji.strokePaths — un chemin par trait,
  // dans l'ordre d'écriture). Source : projet animCJK (svgsJaKana),
  // distribué sous licence LGPL, via kana-svg-data
  // (github.com/hy2k/kana-svg-data). Espace de coordonnées 1024×1024
  // (contrairement aux 109×109 des kanjis) — voir le viewBox du panneau
  // "Ordre des traits" dans KanaCardLoop.tsx.
  strokePaths: string[]
  // Un mot d'exemple courant utilisant ce caractère — pour ancrer la
  // lecture dans un usage réel plutôt qu'une syllabe isolée (demande
  // explicite de l'utilisatrice).
  example: KanaExample
}

